const output = $input.first().json.stdout || '';
const threshold = $('Set Log Config').first().json.alertThreshold || 5;
const lines = output.trim().split('\n').filter(l => l.includes('::'));

const results = lines.map(line => {
  const [logFile, pattern, count, samples] = line.split('::');
  const matchCount = parseInt(count) || 0;
  return {
    logFile: logFile.trim(),
    pattern: pattern.trim(),
    matchCount,
    samples: (samples || '').split('|').filter(s => s.trim()).slice(0, 3),
    exceedsThreshold: matchCount >= threshold,
    severity: matchCount >= threshold * 2 ? 'CRITICAL' : matchCount >= threshold ? 'WARNING' : 'INFO',
    timestamp: new Date().toISOString()
  };
});

if (results.length === 0) {
  return [{ json: { noErrors: true, timestamp: new Date().toISOString() } }];
}

return results.map(r => ({ json: r }));

